import unittest
from candidate import fibfib

class TestFibFib(unittest.TestCase):
    def test_fibfib_zero(self):
        self.assertEqual(fibfib(0), 0)

    def test_fibfib_one(self):
        self.assertEqual(fibfib(1), 0)

    def test_fibfib_two(self):
        self.assertEqual(fibfib(2), 1)

    def test_fibfib_small_numbers(self):
        self.assertEqual(fibfib(3), 1)
        self.assertEqual(fibfib(4), 1)
        self.assertEqual(fibfib(5), 2)
        self.assertEqual(fibfib(6), 3)

    def test_fibfib_large_numbers(self):
        self.assertEqual(fibfib(7), 5)
        self.assertEqual(fibfib(8), 24)
        self.assertEqual(fibfib(9), 133)
        self.assertEqual(fibfib(10), 750)

    def test_fibfib_negative_numbers(self):
        self.assertEqual(fibfib(-1), None)
        self.assertEqual(fibfib(-2), None)
        self.assertEqual(fibfib(-3), None)

    def test_fibfib_large_positive_numbers(self):
        self.assertEqual(fibfib(40), 102334155)
        self.assertEqual(fibfib(50), 354224848179261915075)
        self.assertEqual(fibfib(60), 22615398043372088768288513727)

    def test_fibfib_float(self):
        self.assertAlmostEqual(fibfib(1.5), None)

    def test_fibfib_large_float(self):
        self.assertAlmostEqual(fibfib(4.5), None)

if __name__ == '__main__':
    unittest.main()
